"use strict";

// The INSTANCE-field negative control: byte-for-byte the shape of
// `index.js`'s early branch except that the field carries no `static`
// modifier.
//
// Evaluating this class definition INSTALLS the initializer and runs
// nothing. `bail()` executes only inside a constructor call, which is a
// caller's decision made after this module has finished loading -- so
// module evaluation continues past the class and `module.exports =
// safeOp` really is reached on every load. `safeOp` must therefore stay
// attributable, and a NOT_AFFECTED proof over it stays valid. Withdrawing
// authority here would be a false refusal, not conservatism.
function dangerousOp(input) {
  return "danger:" + input;
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("instance field initializer throws on construction only");
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  class Mode {
    ready = bail();
  }
}

module.exports = safeOp;
